136	/**
137	 * Starts one server in a fresh temp folder for a suite.
138	 * Returns an object whose fields (`port`, `dir`, `dataFile`, `server`) are filled by `before`.
139	 * Usage: const ctx = useServer({ before, after });
140	 */
141	export function useServer({ before, after }, { dataFileName = 'data.json', env = {} } = {}) {
